<?php declare(strict_types=1);use Bulbula\Core\Csrf;use Bulbula\Core\View; ?>
<section class="b-card" style="padding:var(--space-6)"><div style="display:flex;justify-content:space-between;gap:1rem;align-items:start"><div><span class="b-badge b-badge--orange">Administrator only</span><h2 style="margin:var(--space-3) 0">Customer privacy queue</h2><p style="font-size:var(--text-sm);color:var(--neutral-600)">Process verified data-access and deletion requests. Completing deletion anonymizes the Customer identity, preserves public review integrity, and revokes every device.</p></div><span class="b-badge"><?= count($requests) ?> requests</span></div></section>
<div style="display:grid;gap:var(--space-4);margin-top:var(--space-5)"><?php if(empty($requests)): ?><section class="b-card" style="padding:var(--space-6)">No privacy requests are waiting.</section><?php endif; ?><?php foreach($requests as $item): ?><article class="b-card" style="padding:var(--space-5)"><div style="display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap"><div><strong>#<?= (int)$item['id'] ?> · <?= View::e(ucwords(strtolower(str_replace('_',' ',(string)$item['request_type'])))) ?></strong><div style="font-size:var(--text-sm);color:var(--neutral-600)"><?= View::e($item['display_name']??'Customer unavailable') ?> · <?= View::e($item['requester_email']) ?></div><div style="font-size:var(--text-xs);color:var(--neutral-500)">Submitted <?= View::e($item['created_at']) ?></div></div><span class="b-badge <?= $item['status']==='SUBMITTED'?'b-badge--orange':'' ?>"><?= View::e(ucwords(strtolower(str_replace('_',' ',(string)$item['status'])))) ?></span></div><form method="POST" action="/staff/privacy-requests/<?= (int)$item['id'] ?>/resolve" style="display:grid;grid-template-columns:minmax(180px,.35fr) 1fr auto;gap:var(--space-3);margin-top:var(--space-4);align-items:end"><?= Csrf::field() ?><div><label class="b-label">Status</label><select class="b-select" name="status"><option value="IN_PROGRESS">In progress</option><option value="COMPLETED">Completed</option><option value="REJECTED_WITH_REASON">Rejected with reason</option></select></div><div><label class="b-label">Resolution summary</label><input class="b-input" name="resolution_summary" maxlength="1000" value="<?= View::e($item['resolution_summary']??'') ?>" placeholder="Required when closing"></div><button class="b-btn b-btn--primary b-btn--sm" type="submit">Update</button></form></article><?php endforeach; ?></div>
